def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 20.0))

    prev_bids = []
    desperate_pressure = 0.0
    rich_aggressive = 0.0

    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                if float(bid) > desperate_pressure:
                    desperate_pressure = float(bid)
            if opp.get('budget', 0) >= 500 and float(bid) > rich_aggressive:
                rich_aggressive = float(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0
    scarcity = 1.0 - scarcity

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.6
    elif hp <= 6:
        urgency += 0.25

    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.55

    urgency += 0.55 * scarcity

    if day >= 8:
        urgency += 0.2

    if urgency >= 1.6:
        target = max(highest_prev + 2.0, desperate_pressure + 2.0, 124.0)
    elif urgency >= 1.0:
        target = max(highest_prev + 1.5, rich_aggressive + 1.0, 96.0)
    elif scarcity >= 0.75:
        target = max(highest_prev + 1.0, 82.0)
    elif scarcity >= 0.45:
        target = max(58.0, highest_prev * 0.72)
    else:
        target = max(24.0, highest_prev * 0.35)

    if hp >= 8 and no_water == 0 and supply >= 22:
        target = min(target, 38.0)

    reserve_days = max(0, 10 - day)
    reserve = reserve_days * 18.0
    spend_cap = budget - reserve
    if spend_cap < 0:
        spend_cap = budget * 0.55

    if hp <= 3 or no_water >= 2:
        spend_cap = max(spend_cap, budget * 0.92)
    elif hp <= 5 or no_water >= 1:
        spend_cap = max(spend_cap, budget * 0.75)
    else:
        spend_cap = max(spend_cap, budget * 0.45)

    bid = min(float(budget), float(spend_cap), float(target))

    if bid < 0:
        bid = 0.0
    if budget > 0 and hp <= 2:
        bid = max(bid, min(float(budget), 110.0))

    return float(round(bid, 2))

