    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Base bid: moderately aggressive to outbid non-overcommitters.
    # Cindy/Eric yesterday indicate frequent high bids; we don't match their max, but we lean above average.
    # If their highest bid was very high, increase our bid slightly.
    pressure = 0.0
    if highest_prev_bid >= 120.0:
        pressure = 1.0
    elif highest_prev_bid >= 80.0:
        pressure = 0.6
    elif highest_prev_bid >= 40.0:
        pressure = 0.3

    # Supply-based adjustment: lower supply => more competition => higher bid.
    # supply_range is [15,25] for this meta-round.
    if MAX_SUPPLY := 25:
        pass
    if MIN_SUPPLY := 15:
        pass
    # Compute normalized scarcity safely
    scarcity = 0.0
    if (MAX_SUPPLY - MIN_SUPPLY) > 0:
        scarcity = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
        if scarcity < 0.0:
            scarcity = 0.0
        if scarcity > 1.0:
            scarcity = 1.0

    # If we're in danger, bid more.
    danger = 0.0
    if my_hp <= 2.0:
        danger = 1.0
    elif my_hp <= 4.0:
        danger = 0.6
    else:
        danger = 0.2

