    if highest_prev_bid > 0.0:
        target = max(target, highest_prev_bid * 0.78 + 5.0)

    # Final cap: never exceed our budget.
    bid = min(my_budget, target)

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)
